"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisFooterContent } from "./components/footer-sections/content";
import View6 from "./components/footer-sections/variants/07-spotlight";
const variants = {"spotlight":View6};
export type { ArtemisFooterClock, ArtemisFooterColumn, ArtemisFooterColumnLink, ArtemisFooterContent, ArtemisFooterImage, ArtemisFooterLink, ArtemisFooterNewsletter, ArtemisFooterSocialLink } from "./components/footer-sections/content";
export interface ArtemisFooterSectionsProps { className?: string; variant?: "spotlight"; /** The words on the footer; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisFooterContent>; }
export function ArtemisFooterSections({ className, variant = "spotlight", content }: ArtemisFooterSectionsProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link, and where it goes. Links to other sites (http or https) open in a new tab. */
export interface ArtemisFooterLink {
  label: string;
  href: string;
}

/** A link in a column. */
export interface ArtemisFooterColumnLink extends ArtemisFooterLink {
  /** Shows the link in the stronger style, for a "browse all" link. landscape. */
  highlight?: boolean;
}

/** A small heading over a list of links. */
export interface ArtemisFooterColumn {
  title: string;
  links: ArtemisFooterColumnLink[];
}

/** A profile or contact link drawn as an icon. Its label names the link for screen readers, and is its tooltip where the layout has one. */
export interface ArtemisFooterSocialLink extends ArtemisFooterLink {
  /** The icon. Without one, the link keeps the icon the layout draws in that position. */
  icon?: ComponentType<{ className?: string }>;
}

/** A picture, and the words that describe it. */
export interface ArtemisFooterImage {
  src: string;
  alt: string;
}

/** An email sign-up form. */
export interface ArtemisFooterNewsletter {
  /** The heading over the form. */
  title: string;
  /** A line under the heading. */
  text: string;
  /** Sample text in the empty email field. */
  placeholder: string;
  /** The button. */
  button: string;
  /** The button while the address is being sent. */
  sending: string;
  /** The button once the address is sent. */
  sent: string;
}

/** A live clock for one city. */
export interface ArtemisFooterClock {
  /** The city named beside the clock face. */
  city: string;
  /** The city's IANA time zone, such as "Europe/Copenhagen". The clock stays blank if the zone is unknown. */
  timeZone: string;
  /** A line over the time. */
  caption: string;
}

/** The words on an Artemis footer. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisFooterContent {
  /** The name beside the logo mark, and where it links. All layouts; wordmark, spotlight and mega show the name without a link, and wordmark and spotlight also draw it large across the foot. */
  brand: ArtemisFooterLink;
  /** A sentence about the brand. landscape, studio, local-time, frame, spotlight, mega and cta. */
  tagline?: string;
  /** The footer's main line. panorama and wordmark show it as a heading, landscape as a line under `tagline`, studio as a line over `cta`. */
  headline?: string;
  /** The styled end of the headline. It goes with `headline`: give `headline` alone and it shows alone, give both and both show. panorama, wordmark and landscape style it; studio runs it on after `headline`. */
  headlineAccent?: string;
  /** A paragraph under the headline. panorama. */
  subhead?: string;
  /** The main link. panorama and wordmark show it as a button, studio as a large underlined link. */
  cta?: ArtemisFooterLink;
  /** A quieter button beside `cta`. panorama. */
  secondaryCta?: ArtemisFooterLink;
  /** A short status, such as availability. studio and mega show it in a pill with a dot. */
  status?: string;
  /** A picture. panorama shows it wide; studio shows it over `location`. */
  image?: ArtemisFooterImage;
  /** Where you are, beside a map pin. studio. */
  location?: string;
  /** A row of links without headings. panorama and studio, which list the links of `columns` instead when you give only those. */
  links?: ArtemisFooterLink[];
  /** Columns of links under small headings. wordmark, landscape, local-time, frame, spotlight, mega and cta. */
  columns?: ArtemisFooterColumn[];
  /** An email sign-up form. mega. */
  newsletter?: ArtemisFooterNewsletter;
  /** A live clock for one city. local-time. */
  clock?: ArtemisFooterClock;
  /** Icon links to profiles or email. panorama, landscape, studio, frame, mega and cta. */
  social?: ArtemisFooterSocialLink[];
  /** The copyright line. All layouts but landscape. */
  legal?: string;
  /** Small links beside the copyright line. panorama, studio, local-time, frame and cta. */
  legalLinks?: ArtemisFooterLink[];
  /** A short closing line near the copyright. wordmark, frame and spotlight. */
  note?: string;
}

"use client";
// @zeus-internal
import type { PointerEvent } from "react";
import { motion, useMotionTemplate, useMotionValue, useReducedMotion, useSpring } from "motion/react";
import type { ArtemisFooterContent } from "../content";
const SPOTLIGHT_SPRING = { stiffness: 400, damping: 30, mass: 0.6 };
const DEFAULT = {
    brand: { label: "Artemis Pro", href: "/" },
    tagline: "Premium motion components and blocks for modern React apps.",
    columns: [
        { title: "Product", links: [{ label: "Components", href: "#" }, { label: "Blocks", href: "#" }, { label: "Templates", href: "#" }, { label: "Pricing", href: "#" }, { label: "Changelog", href: "#" }] },
        { title: "Developers", links: [{ label: "Documentation", href: "#" }, { label: "Registry", href: "#" }, { label: "CLI", href: "#" }, { label: "Examples", href: "#" }] },
        { title: "Company", links: [{ label: "About", href: "#" }, { label: "Blog", href: "#" }, { label: "Careers", href: "#" }, { label: "Contact", href: "#" }] },
    ],
    legal: "\u00A9 2026 Artemis Pro. All rights reserved.",
    note: "Thoughtfully made. Ready for what\u2019s next.",
} satisfies ArtemisFooterContent;
/** Links to other sites open in a new tab. */
const newTab = (href: string) => (/^https?:/.test(href) ? { target: "_blank", rel: "noreferrer noopener" } : {});
export default function FooterSectionsSpotlight({ content }: { content?: Partial<ArtemisFooterContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const x = useSpring(0, SPOTLIGHT_SPRING);
    const y = useSpring(0, SPOTLIGHT_SPRING);
    const opacity = useMotionValue(0);
    const reduceMotion = useReducedMotion();
    const maskImage = useMotionTemplate `radial-gradient(200px at ${x}px ${y}px, black, transparent 70%)`;
    const move = (event: PointerEvent<HTMLDivElement>) => {
        if (reduceMotion)
            return;
        const rect = event.currentTarget.getBoundingClientRect();
        x.set(event.clientX - rect.left);
        y.set(event.clientY - rect.top);
    };
    return (<>
      <div className="art:w-full">
        <footer className="art:relative art:w-full art:overflow-hidden art:border-t art:border-border art:bg-background">
          <div className="art:mx-auto art:w-full art:max-w-6xl art:px-4 art:pt-16 art:@min-[640px]/artemis:px-8">
            <div className="art:grid art:gap-12 art:@min-[1024px]/artemis:grid-cols-[1.4fr_2fr]">
              <div className="art:flex art:flex-col">
                <div className="art:flex art:items-center art:gap-3">
                  <span aria-hidden="true" className="art:grid art:size-10 art:place-items-center art:rounded-full art:border art:border-border">
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-layers art:size-4 art:text-foreground" aria-hidden="true">
                      <path d="M12.83 2.18a2 2 0 0 0-1.66 0L2.6 6.08a1 1 0 0 0 0 1.83l8.58 3.91a2 2 0 0 0 1.66 0l8.58-3.9a1 1 0 0 0 0-1.83z"/>
                      <path d="M2 12a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 12"/>
                      <path d="M2 17a1 1 0 0 0 .58.91l8.6 3.91a2 2 0 0 0 1.65 0l8.58-3.9A1 1 0 0 0 22 17"/>
                    </svg>
                  </span>
                  <span className="art:font-sans art:text-foreground art:text-xl art:font-medium">
                    {copy.brand.label}
                  </span>
                </div>
                <p className="art:mt-3 art:max-w-xs art:text-pretty art:text-muted-foreground art:text-sm art:leading-6">
                  {copy.tagline}
                </p>
              </div>
              <div className="art:grid art:grid-cols-2 art:gap-8 art:@min-[640px]/artemis:grid-cols-3">
                {copy.columns.map((column, index) => <nav key={index} aria-label={column.title} className="art:flex art:flex-col">
                  <p className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-wider">
                    {column.title}
                  </p>
                  <ul className="art:mt-3 art:flex art:flex-col art:gap-1">
                    {column.links.map((link, linkIndex) => <li key={linkIndex}>
                      <a href={link.href} {...newTab(link.href)} className="art:group art:inline-flex art:min-h-10 art:w-fit art:items-center art:gap-1.5 art:rounded-full art:text-muted-foreground art:text-sm art:transition-colors art:hover:text-foreground art:focus-visible:text-foreground art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-ring">
                        {link.label}
                      </a>
                    </li>)}
                  </ul>
                </nav>)}
              </div>
            </div>
            <div className="art:mt-10 art:flex art:flex-wrap art:items-center art:justify-between art:gap-3 art:border-t art:border-border art:pt-5 art:text-xs art:text-muted-foreground">
              <p>
                {copy.legal}
              </p>
              <span>
                {copy.note}
              </span>
            </div>
            <div className="art:relative art:mt-6 art:select-none art:overflow-hidden" onPointerEnter={(event) => {
            if (reduceMotion)
                return;
            opacity.set(1);
            move(event);
        }} onPointerMove={move} onPointerLeave={() => opacity.set(0)}>
              <svg aria-hidden="true" viewBox="0 32 624 104" className="art:block art:h-auto art:w-full">
                <text x="0" y="136" textLength="624" lengthAdjust="spacingAndGlyphs" fill="none" stroke="currentColor" strokeWidth="0.5" className="art:font-sans art:text-9xl art:font-medium art:text-foreground/20">
                  {copy.brand.label}
                </text>
              </svg>
              {reduceMotion ? (<div aria-hidden="true" className="art:absolute art:inset-0 art:text-foreground/10">
                  <svg aria-hidden="true" viewBox="0 32 624 104" className="art:block art:h-auto art:w-full">
                    <text x="0" y="136" textLength="624" lengthAdjust="spacingAndGlyphs" fill="currentColor" stroke="none" strokeWidth="0.5" className="art:font-sans art:text-9xl art:font-medium">
                      {copy.brand.label}
                    </text>
                  </svg>
                </div>) : (<motion.div aria-hidden="true" className="art:absolute art:inset-0 art:text-primary" style={{ opacity, maskImage }}>
                  <svg aria-hidden="true" viewBox="0 32 624 104" className="art:block art:h-auto art:w-full">
                    <text x="0" y="136" textLength="624" lengthAdjust="spacingAndGlyphs" fill="currentColor" stroke="none" strokeWidth="0.5" className="art:font-sans art:text-9xl art:font-medium">
                      {copy.brand.label}
                    </text>
                  </svg>
                </motion.div>)}
              <span className="art:sr-only">
                {copy.brand.label}
              </span>
            </div>
          </div>
        </footer>
      </div>
    </>);
}
